import{z as A,x as i,o as r,c as d,q as t,j as B,D as e,d as n,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"贸易与增长","description":"","frontmatter":{"title":"贸易与增长","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/trade-growth.md","filePath":"econ/trade-growth.md","lastUpdated":1791063341000}'),p={name:"econ/trade-growth.md"};function m(D,a,F,u,h,f){const o=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="贸易与增长" tabindex="-1">贸易与增长 <a class="header-anchor" href="#贸易与增长" aria-label="Permalink to &quot;贸易与增长&quot;">​</a></h1><div class="epigraph"><p>静态比较利益是一次水平效应；增长问的是贸易是否改变创新与资本积累的斜率。工具若只推动收入水平，不能把回归里的开放系数读成增长率。</p><footer>—— Frankel and Romer, Does Trade Cause Growth?, AER 1999；Grossman and Helpman, Innovation and Growth in the Global Economy</footer></div><p><a href="/econ/offshoring-tasks">上一课</a>把贸易收到任务。贸易理论课序在此收束长期。下一单元国际金融续从 Lucas 悖论起：资本为何不按教科书流向穷国。本课钉贸易与增长的水平 / 增长效应，以及识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态李嘉图 / Krugman / Melitz 给出开放后的<strong>水平</strong>（实际收入一次跳升）。内生增长：贸易扩大市场（创新租金）、扩散技术、或通过竞争消灭模仿——斜率可以变。Frankel–Romer：用地理构造的贸易预测值当 IV，估贸易份额对收入水平的效应，发现正且大于 OLS。缺口是：那是水平（或长期水平），不是每年增长率；地理工具排除「收入高所以贸易多」的反向，不排除地理还通过制度、疾病进收入（后续批评）。Rodriguez–Rodrik：开放指标与政策内生，简单跨国回归不可信。</p><p><span class="marginnote">Grossman–Helpman：开放对创新的符号取决于知识溢出是国际的还是国内的、以及竞争是偷走租金还是扩大市场。理论不定，要机制而不是一条 \\(\\beta\\)。</span></p><p><span class="marginnote">直觉类比：「水平效应」像把自行车换成电动车——速度一下子提上去一截；「增长效应」像换了一台更强的发动机，让以后每天都更快。增长文献问的是斜率有没有变，不是有没有一次跳升。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>水平 vs 增长：在 AK / 半内生增长里，开放可以只抬水平（资本向新稳态过渡时表现为暂时高增长）。实证要声明因变量是 \\(\\ln y\\) 还是 \\(\\Delta\\ln y\\)。IV：地理（FR）、政策突变、关税时间表；每一个都有排除故事。Melitz 动态（Atkeson–Burstein、Sampson）把选择与创新连起来：贸易改变创新激励，斜率可以动。本课不估新的 \\(\\beta\\)。</p>',9)),(r(),B(s,null,{default:e(()=>[l(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%E8%B4%B8%E6%98%93%22%5D%20--%3E%20LEV%5B%22%E6%B0%B4%E5%B9%B3%3A%20%E5%AE%9E%E9%99%85%E6%94%B6%E5%85%A5%E8%B7%B3%E5%8D%87%22%5D%0A%20%20INN%5B%22%E5%88%9B%E6%96%B0%20%2F%20%E6%89%A9%E6%95%A3%22%5D%20--%3E%20SLOPE%5B%22%E5%8F%AF%E8%83%BD%E6%94%B9%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%0A%20%20FR%5B%22%E5%9C%B0%E7%90%86%20IV%22%5D%20--%3E%20Y%5B%22%E5%AF%B9%E6%94%B6%E5%85%A5%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20GEO%5B%22%E5%9C%B0%E7%90%86%E4%B9%9F%E8%BF%9B%E5%88%B6%E5%BA%A6%22%5D%20--%3E%20EX%5B%22%E6%8E%92%E9%99%A4%E4%B8%8D%E5%B9%B2%E5%87%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与计量课程：这是 IV 在宏观跨国，弱工具与排除的课都适用。不要用 DML 替代地理故事。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：「IV」（工具变量）就是找一个只通过「贸易」影响收入、而不直接影响收入的外生帮手变量。Frankel–Romer 用「由地理决定的贸易量」当这个帮手——邻居多不多、离海远不远，不是政策自己选的。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"机制候选三条。市场扩大：出口提高创新租金（Krugman / 内生增长）。知识扩散：进口品种与 FDI 带技术（Coe–Helpman 溢出）。竞争：减少惰性或偷走租金（Schumpeter 两刃）。资本积累：开放改实际利率与 \\(K\\) 路径，仍可能只是水平。穷国若制度差，开放可以把资源配置到寻租而不是创新——增长效应可以负。",-1)),a[7]||(a[7]=E("p",null,"与 China shock：局部劳动市场损失是过渡与摩擦；增长文献问几十年的 \\(y\\)。两套时间尺度，不要用 CZ 十年就业否证 Frankel–Romer 的水平效应，也不要用跨国 \\(\\beta\\) 否认 ADH。",-1)),(r(),B(s,null,{default:e(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22%E5%BC%80%E6%94%BE%E8%B4%B8%E6%98%93%22%5D%20--%3E%20MKT%5B%22%E5%B8%82%E5%9C%BA%E6%89%A9%E5%A4%A7%3A%20%E5%88%9B%E6%96%B0%E7%A7%9F%E9%87%91%E4%B8%8A%E5%8D%87%22%5D%0A%20%20OPEN%20--%3E%20KNOW%5B%22%E7%9F%A5%E8%AF%86%E6%89%A9%E6%95%A3%3A%20%E8%BF%9B%E5%8F%A3%E5%93%81%E7%A7%8D%E4%B8%8E%20FDI%20%E5%B8%A6%E6%8A%80%E6%9C%AF%22%5D%0A%20%20OPEN%20--%3E%20COMP%5B%22%E7%AB%9E%E4%BA%89%E5%8A%A0%E5%89%A7%3A%20%E6%B7%98%E6%B1%B0%E6%83%B0%E6%80%A7%20%2F%20%E5%81%B7%E8%B5%B0%E7%A7%9F%E9%87%91%22%5D%0A%20%20MKT%20--%3E%20POS%5B%22%E5%80%BE%E5%90%91%E6%8F%90%E9%AB%98%E5%A2%9E%E9%95%BF%22%5D%0A%20%20KNOW%20--%3E%20POS%0A%20%20COMP%20--%3E%20AMB%5B%22%E6%96%B9%E5%90%91%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20OPEN%20--%3E%20KACC%5B%22%E8%B5%84%E6%9C%AC%E7%A7%AF%E7%B4%AF%3A%20%E5%A4%9A%E4%B8%BA%E6%B0%B4%E5%B9%B3%E6%95%88%E5%BA%94%22%5D%0A%20%20RENT%5B%22%E5%88%B6%E5%BA%A6%E5%B7%AE%3A%20%E8%B5%84%E6%BA%90%E6%B5%81%E5%90%91%E5%AF%BB%E7%A7%9F%22%5D%20--%3E%20NEG%5B%22%E5%A2%9E%E9%95%BF%E6%95%88%E5%BA%94%E5%8F%AF%E4%B8%BA%E8%B4%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">常见误区：初学者容易把「开放的国家更富」读成「开放让经济每年增长更快」。前者是收入水平更高（一次跳升），后者是增长率更高（斜率变陡）——跨国回归里因变量是 \\(\\ln y\\) 还是 \\(\\Delta\\ln y\\)，读出的东西完全不同。</span></p><p><span class="marginnote">贸易课序到此：比较成本、禀赋与分配、IRS 与品种、异质企业、引力与 EK、关税与协定、价值链、中国冲击、任务、增长。下一单元资本流动之谜，货物理论当背景不再重推。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣称「开放一定加快增长」。不重写<a href="/econ/solow-1956-paper">索洛</a>附录。国际金融续的 Lucas 悖论问的是资本为何不流向穷国，与本课「贸易是否提高 \\(A\\)」相关但对象是 \\(K\\) 的跨境，不是货物。不要把 FTA 虚拟变量的增长回归当成 Bagwell–Staiger 的福利。</p><p>后课默认：静态贸易给水平；增长效应要创新 / 积累机制，理论符号不定。Frankel–Romer 是水平 IV，排除有争议。局部冲击证据与长期跨国证据分层。下一课 Lucas 悖论：资本不按边际产出流向穷国。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态比较利益主要是水平效应；增长要斜率机制。</li><li>Frankel–Romer 地理 IV 对准收入水平，排除不完美。</li><li>Grossman–Helpman：市场、溢出、竞争三通道，符号不定。</li><li>局部劳动市场损失不自动否证长期水平增益。</li><li>出处：Frankel and Romer, <em>AER</em> 1999；Grossman and Helpman；Rodriguez and Rodrik。</li></ul>',7))])}const k=A(p,[["render",m]]);export{g as __pageData,k as default};
